const body = $input.first().json.body || {};
const value = body && body.entry && body.entry[0] && body.entry[0].changes && body.entry[0].changes[0] && body.entry[0].changes[0].value;
const message = value && value.messages && value.messages[0];
if (!message) return [{ json: { skip: true } }];
const contact = value.contacts && value.contacts[0];
let text = '[no-texto]';
if (message.type === 'text') text = ((message.text && message.text.body) || '').trim();
else if (message.type === 'interactive') text = String((message.interactive && message.interactive.button_reply && message.interactive.button_reply.id) || (message.interactive && message.interactive.list_reply && message.interactive.list_reply.id) || (message.interactive && message.interactive.button_reply && message.interactive.button_reply.title) || '').trim();
else if (message.type === 'button') text = ((message.button && message.button.text) || '').trim();
return [{ json: { skip: false, wa_id: message.from, message_type: message.type, message_text: text, message_id: message.id, sender_name: (contact && contact.profile && contact.profile.name) || 'Huésped' } }];

const p = $('Parsear Mensaje Meta').first().json;
const raw = $input.first().json.value;
let S = {};
if (typeof raw === 'string' && raw.trim()) { try { S = JSON.parse(raw); } catch (e) { S = {}; } }
else if (raw && typeof raw === 'object') { S = raw; }
if (!S || typeof S !== 'object' || Array.isArray(S)) S = {};
const norm = (s) => String(s == null ? '' : s).toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '').trim();
const t = norm(p.message_text);
const state = S.state || 'menu';
const step = S.step || 'inicio';
const RESTART = ['hola','menu','inicio','reiniciar','start','hi','hello','buenas','buenos dias','buenas tardes','buenas noches'];
const restartRequested = RESTART.includes(t);
const agentActive = !restartRequested && (S.agent_active === true || S.agent_active === 'true');
const AGENT = /\b(agente|recepcionista|humano)\b/;
const textual = ['text','interactive','button'].includes(p.message_type);
let route = state + ':' + step;
if (!textual) route = 'no_texto';
else if (restartRequested) route = 'menu:inicio';
else if (AGENT.test(t) && state !== 'escribir_resena') route = 'escalamiento:inicio';
else if (state === 'escalamiento') route = 'menu:inicio';
return [{ json: { wa_id: p.wa_id, sender_name: p.sender_name, message_text: p.message_text, message_type: p.message_type, agent_active: agentActive, session: S, route } }];

const J = $input.first().json;
const text = String(J.message_text || '').trim().toLowerCase();
const ids = { menu_reserva: '1', menu_ia: '2', menu_resenas: '3', menu_escribir_resena: '4', menu_agente: '5', menu_cancelar: '6' };
const normalized = ids[text] || text;
const m = normalized.replace(/[\uFE0F\u20E3]/g, '').match(/^\D*([1-6])\D*$/);
return [{ json: Object.assign({}, J, { opcion: m ? m[1] : 'invalido' }) }];

const J = $input.first().json;
const wa_id = J.wa_id;
const sender_name = J.sender_name || 'Huésped';
return [{ json: { wa_id, sender_name, response_text: '📅 ¡Perfecto! Iniciemos tu reserva.

¿Cuál es tu fecha de *llegada*?
Formato: AAAA-MM-DD
Ejemplo: _2026-10-12_', session: { state: 'reserva', step: 'checkin', agent_active: false, wa_id, sender_name, reservation_draft: {} } } }];

const J = $input.first().json;
const now = Date.now();
const session = Object.assign({}, J.session || { state: 'menu', step: 'inicio', agent_active: false }, { last_activity: now });
return [{ json: { wa_id: J.wa_id, response_text: J.response_text || 'Entendido. Procesando...', response_payload: J.response_payload || null, redis_key: 'session:' + J.wa_id, redis_value: JSON.stringify(session), last_activity: now } }];

const raw = $input.first().json.value;
let session = {};
try { session = typeof raw === 'string' ? JSON.parse(raw) : (raw || {}); } catch (error) {}
const stored = Number(session.last_activity || 0);
const mine = Number($('Preparar Salida').first().json.last_activity || 0);
// Solo avisamos si la sesión sigue reflejando la actividad de ESTA ejecución.
// Si el usuario respondió, una ejecución posterior sobrescribió last_activity y stored !== mine,
// así el aviso no se envía. Esto garantiza que el aviso salga una sola vez y solo ante inactividad real.
const sameSession = stored > 0 && stored === mine;
const elapsed = Date.now() - stored >= 600000;
return [{ json: { wa_id: $('Preparar Salida').first().json.wa_id, redis_key: $('Preparar Salida').first().json.redis_key, stale: sameSession && elapsed } }];

const raw = $input.first().json.value;
let session = {};
try { session = typeof raw === 'string' ? JSON.parse(raw) : (raw || {}); } catch (error) {}
const stored = Number(session.last_activity || 0);
const mine = Number($('Preparar Salida').first().json.last_activity || 0);
// Solo borramos si no hubo actividad nueva (misma sesión) y ya pasaron 11 min.
const sameSession = stored > 0 && stored === mine;
const elapsed = Date.now() - stored >= 660000;
return [{ json: { redis_key: $('Preparar Salida').first().json.redis_key, stale: sameSession && elapsed } }];

const J = $input.first().json;
const wa_id = J.wa_id;
const sender_name = J.sender_name || 'Huésped';
return [{ json: { wa_id, sender_name, response_text: '🚧 Esa opción estará disponible muy pronto. Escribe *menú* para volver al inicio.', session: { state: 'menu', step: 'esperando_opcion', agent_active: false, wa_id, sender_name, reservation_draft: {} } } }];

const J = $input.first().json;
const wa_id = J.wa_id;
const sender_name = J.sender_name || 'Huésped';
const prev = J.session || {};
const hourCO = Number(new Intl.DateTimeFormat('en-US', { timeZone: 'America/Bogota', hour: '2-digit', hour12: false }).format(new Date()));
const available = hourCO >= 7 && hourCO < 23;
if (!available) return [{ json: { wa_id, sender_name, agent_available: false, response_text: '🕘 En este momento recepción está fuera de horario. Atendemos todos los días de *7:00 a. m. a 11:00 p. m.*. Escribe *menú* para continuar con el asistente.', session: { state: 'menu', step: 'esperando_opcion', agent_active: false, wa_id, sender_name, reservation_draft: prev.reservation_draft || {} } } }];
return [{ json: { wa_id, sender_name, agent_available: true, response_text: '👤 En un momento un miembro de nuestro equipo de *Satori Hotel* continuará esta conversación contigo. ¡Gracias por tu paciencia! ☕', session: { state: 'escalamiento', step: 'atendido', agent_active: true, wa_id, sender_name, reservation_draft: prev.reservation_draft || {} } } }];

const J = $input.first().json;
const wa_id = J.wa_id;
const sender_name = J.sender_name || 'Huésped';
return [{ json: { wa_id, sender_name, response_text: '⚠️ No entendí tu elección. Por favor responde con un número del *1* al *6*.', session: { state: 'menu', step: 'esperando_opcion', agent_active: false, wa_id, sender_name, reservation_draft: {} } } }];

const J = $input.first().json;
const wa_id = J.wa_id;
const sender_name = J.sender_name || 'Huésped';
const msg = '¡Hola, ' + sender_name + '\n! Bienvenido al asistente de *Satori Hotel* \n\nSelecciona una opción para continuar.';
// SOLUCIÓN: Se acortó "Reservar con asistente IA" a "Asistente IA" para no superar 24 caracteres
const rows = [
  ['menu_reserva', 'Hacer una reserva', 'Reserva tradicional'], 
  ['menu_ia', 'Asistente IA', 'Próximamente'], 
  ['menu_resenas', 'Ver reseñas del hotel', 'Opiniones de huéspedes'], 
  ['menu_escribir_resena', 'Escribir una reseña', 'Comparte tu experiencia'], 
  ['menu_agente', 'Hablar con un agente', 'Recepción'], 
  ['menu_cancelar', 'Cancelar reserva', 'Consulta políticas']
].map(([id, title, description]) => ({ id, title, description }));

return [{ json: { wa_id, sender_name, response_text: msg, response_payload: { type: 'interactive', interactive: { type: 'list', body: { text: msg }, action: { button: 'Ver opciones', sections: [{ title: 'Satori Hotel', rows }] } } }, session: { state: 'menu', step: 'esperando_opcion', agent_active: false, wa_id, sender_name, reservation_draft: {} } } }];

const J = $input.first().json;
const wa_id = J.wa_id;
const sender_name = J.sender_name || 'Huésped';
const text = String(J.message_text || '').trim();
const hoyCO = new Date(Date.now() - 5 * 3600 * 1000).toISOString().slice(0, 10);
const parseDate = (s) => { s = String(s || '').trim(); const m = s.match(/^(\d{4})-(\d{1,2})-(\d{1,2})$/); if (!m) return null; const iso = m[1] + '-' + m[2].padStart(2,'0') + '-' + m[3].padStart(2,'0'); return isNaN(new Date(iso + 'T00:00:00Z')) ? null : iso; };
const draft = (J.session && J.session.reservation_draft) || {};
const f = parseDate(text);
if (!f) return [{ json: { wa_id, sender_name, response_text: '⚠️ No reconocí la fecha. Usa el formato AAAA-MM-DD (Ejemplo: 2026-10-12)', session: { state: 'reserva', step: 'checkin', agent_active: false, wa_id, sender_name, reservation_draft: draft } } }];
if (f < hoyCO) return [{ json: { wa_id, sender_name, response_text: '⚠️ La fecha de llegada no puede estar en el pasado. ¿Cuál es tu fecha de llegada?', session: { state: 'reserva', step: 'checkin', agent_active: false, wa_id, sender_name, reservation_draft: draft } } }];
return [{ json: { wa_id, sender_name, response_text: '✅ Llegada: *' + f + '*\n\n¿Cuál es la fecha de *salida*?\nFormato: AAAA-MM-DD', session: { state: 'reserva', step: 'checkout', agent_active: false, wa_id, sender_name, reservation_draft: { checkIn: f } } } }];

const J = $input.first().json;
const wa_id = J.wa_id;
const sender_name = J.sender_name || 'Huésped';
const text = String(J.message_text || '').trim();
const draft = (J.session && J.session.reservation_draft) || {};
const parseDate = (s) => { s = String(s || '').trim(); const m = s.match(/^(\d{4})-(\d{1,2})-(\d{1,2})$/); if (!m) return null; const iso = m[1] + '-' + m[2].padStart(2,'0') + '-' + m[3].padStart(2,'0'); const date = new Date(iso + 'T00:00:00Z'); return !isNaN(date.getTime()) && date.toISOString().slice(0, 10) === iso ? iso : null; };
const checkIn = parseDate(draft.checkIn);
if (!checkIn) return [{ json: { wa_id, sender_name, response_text: '⚠️ Perdí la fecha de llegada. Indícala nuevamente con formato AAAA-MM-DD (Ejemplo: 2026-10-12)', session: { state: 'reserva', step: 'checkin', agent_active: false, wa_id, sender_name, reservation_draft: {} } } }];
const f = parseDate(text);
const base = { state: 'reserva', step: 'checkout', agent_active: false, wa_id, sender_name, reservation_draft: Object.assign({}, draft, { checkIn }) };
if (!f) return [{ json: { wa_id, sender_name, response_text: '⚠️ No reconocí la fecha. Usa el formato AAAA-MM-DD (Ejemplo: 2026-10-15)', session: base } }];
if (f <= checkIn) return [{ json: { wa_id, sender_name, response_text: '⚠️ La fecha de salida debe ser posterior a la de llegada (*' + checkIn + '*). ¿Cuál es tu fecha de salida?', session: base } }];
const nd = Object.assign({}, draft, { checkIn, checkOut: f, adults: 1, children: 0, hasPet: false });
return [{ json: { wa_id, sender_name, api_action: 'availability', checkIn: nd.checkIn, checkOut: nd.checkOut, adults: nd.adults, children: nd.children, pet: nd.hasPet, session: { state: 'reserva', step: 'seleccion_habitacion', agent_active: false, wa_id, sender_name, reservation_draft: nd } } }];

const source = $('H F1 CheckOut').first().json;
const raw = $input.all().map((item) => item.json);
const rooms = raw.length === 1 && Array.isArray(raw[0]) ? raw[0] : raw;
const wa_id = source.wa_id;
const sender_name = source.sender_name;
const choices = rooms.slice(0, 10);
const draft = Object.assign({}, source.session.reservation_draft, { availableRooms: choices });
if (!choices.length) return [{ json: { wa_id, sender_name, response_text: '😔 No encontré habitaciones disponibles para esas fechas. Escribe *menú* para iniciar otra búsqueda.', session: { state: 'menu', step: 'esperando_opcion', agent_active: false, wa_id, sender_name, reservation_draft: {} } } }];
const lines = choices.map((room, index) => (index + 1) + '. ' + (room.name || room.type || 'Habitación') + ' #' + (room.number || room.id) + ' - $' + (room.pricePerNight || '?') + '/noche');
const text = '✅ Encontré estas habitaciones para *' + draft.checkIn + '* al *' + draft.checkOut + '*\n\n' + lines.join('\n') + '\n\nEscribe el número de una o varias, separados por coma (por ejemplo: *1, 3*). Cada habitación se bloqueará por 15 minutos.';
return [{ json: { wa_id, sender_name, response_text: text, session: { state: 'reserva', step: 'seleccion_habitacion', agent_active: false, wa_id, sender_name, reservation_draft: draft } } }];

const J = $input.first().json;
const wa_id = J.wa_id;
const sender_name = J.sender_name || 'Huésped';
return [{ json: { wa_id, sender_name, response_text: '📎 Por ahora solo puedo procesar mensajes de texto. Escribe *menú* para ver las opciones.', session: { state: 'menu', step: 'esperando_opcion', agent_active: false, wa_id, sender_name, reservation_draft: {} } } }];

const J = $input.first().json;
const session = J.session || {};
const draft = Object.assign({}, session.reservation_draft || {}, { step: session.step || 'inicio' });
return [{ json: Object.assign({}, J, { session: Object.assign({}, session, { reservation_draft: draft }) }) }];

const J = $input.first().json;
const step = J.session.step;
const today = new Date(Date.now() - 5 * 3600 * 1000).toISOString().slice(0, 10);
const prompt = 'Eres un intérprete de respuestas para el paso actual de una reserva de hotel. No tomas decisiones de negocio, no confirmas disponibilidad, precios ni reservas. Interpreta únicamente la respuesta del usuario para la pregunta indicada. Devuelve solo JSON válido con las propiedades answer (string o null) y confidence (número entre 0 y 1). Si la respuesta es ambigua o no responde la pregunta, usa answer=null.\nFecha actual en Colombia: ' + today + '.\nPaso: ' + step + '.\nReglas: checkin/checkout => fecha YYYY-MM-DD; acepta fechas relativas solo si se resuelven sin ambigüedad desde la fecha actual. huespedes => cantidades numéricas en formato 2 adultos y 1 niño, niños puede ser 0. mascota => SI o NO. confirmacion => CONFIRMAR o CANCELAR solo ante intención explícita.\nRespuesta del usuario: ' + String(J.message_text || '');
return [{ json: Object.assign({}, J, { geminiSource: J, geminiRequest: { contents: [{ parts: [{ text: prompt }] }], generationConfig: { temperature: 0, responseMimeType: 'application/json' } } }) }];

const response = $input.first().json;
const source = $('H Preparar Contexto Gemini').first().json.geminiSource;
let answer = null;
let confidence = 0;
try {
  const raw = response.candidates?.[0]?.content?.parts?.map((part) => part.text || '').join('') || '';
  const parsed = JSON.parse(raw.replace(/^```(?:json)?\s*|\s*```$/g, ''));
  answer = typeof parsed.answer === 'string' ? parsed.answer.trim() : null;
  confidence = Number(parsed.confidence || 0);
} catch (error) {}
const accepted = answer && confidence >= 0.75 ? answer : null;
return [{ json: Object.assign({}, source, { interpreted_answer: accepted }) }];

const J = $input.first().json;
const step = J.session?.step;
const original = String(J.message_text || '').trim();
let text = String(J.interpreted_answer || original).trim();
if (J.session?.state === 'reserva' && step === 'confirmacion') {
  const normalized = original.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '').replace(/[.,!?;:]/g, ' ').replace(/\s+/g, ' ').trim();
  const affirmative = /^(si( confirmo)?|si claro|claro( que si)?|confirmo|confirmar|continuar|correcto|de acuerdo|esta bien|listo|de una|por supuesto)$/.test(normalized);
  const negative = /^(no|no gracias|cancelar|cancelo|cancelar reserva|mejor no)$/.test(normalized);
  if (affirmative !== negative) text = affirmative ? 'confirmar' : 'cancelar';
}
if (J.session?.state === 'reserva' && step === 'huespedes') {
  const words = { cero: '0', un: '1', uno: '1', una: '1', dos: '2', tres: '3', cuatro: '4', cinco: '5', seis: '6', siete: '7', ocho: '8', nueve: '9', diez: '10', once: '11', doce: '12', trece: '13', catorce: '14', quince: '15', dieciseis: '16', diecisiete: '17', dieciocho: '18', diecinueve: '19', veinte: '20' };
  text = text.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '').replace(/\b(cero|un|uno|una|dos|tres|cuatro|cinco|seis|siete|ocho|nueve|diez|once|doce|trece|catorce|quince|dieciseis|diecisiete|dieciocho|diecinueve|veinte)\b/g, (word) => words[word]);
}
return [{ json: Object.assign({}, J, { message_text: text }) }];

const J = $input.first().json;
const D = J.session?.reservation_draft || {};
const keep = (draft, step) => ({ state: 'reserva', step, agent_active: false, wa_id: J.wa_id, sender_name: J.sender_name, reservation_draft: draft });
const reply = (message, session) => [{ json: { wa_id: J.wa_id, sender_name: J.sender_name, response_text: message, session, api_action: 'reply' } }];
if (J.route === 'reserva:seleccion_habitacion') {
  const rooms = Array.isArray(D.availableRooms) ? D.availableRooms : [];
  const input = String(J.message_text || '').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '');
  const words = { uno: '1', un: '1', una: '1', dos: '2', tres: '3', cuatro: '4', cinco: '5', seis: '6', siete: '7', ocho: '8', nueve: '9', diez: '10' };
  const digits = input.replace(/\b(uno|un|una|dos|tres|cuatro|cinco|seis|siete|ocho|nueve|diez)\b/g, (word) => words[word]).match(/\d+/g) || [];
  const indices = [...new Set(digits.map(Number).filter((number) => number >= 1 && number <= rooms.length))];
  const selected = indices.map((number) => rooms[number - 1]);
  if (!selected.length) return reply('⚠️ No reconocí la selección. Responde con los números de la lista, separados por coma; por ejemplo: *1, 3*.', keep(D, 'seleccion_habitacion'));
  return selected.map((room) => ({ json: Object.assign({}, J, { api_action: 'lock', roomId: room.id, checkIn: D.checkIn, checkOut: D.checkOut, selectedRooms: selected, lockRoom: room }) }));
}
if (D.step === 'confirmacion') {
  const answer = String(J.message_text || '').toLowerCase().trim();
  if (['confirmar', 'si', 'sí', 'reserva_confirmar', 'continuar'].includes(answer)) return [{ json: J }];
  if (['cancelar', 'no', 'reserva_cancelar'].includes(answer)) return reply('Reserva cancelada. Escribe *menú* para volver al inicio.', { state: 'menu', step: 'esperando_opcion', agent_active: false, wa_id: J.wa_id, sender_name: J.sender_name, reservation_draft: {} });
  return reply('No entendí tu respuesta y no he confirmado ni cancelado la reserva. Responde *Sí, confirmar* o *No, cancelar*.', keep(D, 'confirmacion'));
}
if (D.step === 'acompanantes') {
  const normalized = String(J.message_text || '').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '').trim();
  const none = /^(ninguno|ninguna|ningun|no hay|nadie|solo yo|solo el titular)[.! ]*$/.test(normalized);
  const expected = Math.max(0, Number(D.adults || 0) + Number(D.children || 0) - 1);
  if (none && expected > 0) return reply('Antes indicaste que se hospedan ' + (expected + 1) + ' personas. ¿Cuáles son los nombres de tus ' + expected + ' acompañante(s)? Si cambió el número de huéspedes, vuelve a indicarlo.', keep(D, 'acompanantes'));
  if (!none && expected === 0) return reply('Según los huéspedes registrados, solo se hospeda la persona titular. Indica *ninguno* o vuelve a escribir cuántos adultos y niños se hospedarán.', keep(D, 'huespedes'));
}
return [{ json: J }];

const J = $input.first().json;
const D = (J.session && J.session.reservation_draft) || {};
const text = String(J.message_text || '').trim();
const normalized = text.toLowerCase();
const keep = (draft, step) => ({ state: 'reserva', step, agent_active: false, wa_id: J.wa_id, sender_name: J.sender_name, reservation_draft: draft });
const output = (response_text, session, extra = {}) => ({ json: Object.assign({ wa_id: J.wa_id, sender_name: J.sender_name, response_text, session }, extra) });
if (J.route === 'reserva:seleccion_habitacion') {
  const rooms = Array.isArray(D.availableRooms) ? D.availableRooms : [];
  const number = Number((normalized.match(/\d+/) || [])[0]);
  const room = rooms.find((item, index) => String(item.id) === normalized.replace('room_', '') || String(item.id) === normalized || index + 1 === number);
  if (!room) return [output('⚠️ No reconocí la habitación. Usa el botón de la lista o responde con su número.', keep(D, 'seleccion_habitacion'))];
  const draft = Object.assign({}, D, { roomId: room.id, room, adults: 1, children: 0, hasPet: false });
  return [output('🔒 Estoy bloqueando temporalmente la habitación seleccionada...', keep(draft, 'bloqueando'), { api_action: 'lock', roomId: room.id, checkIn: D.checkIn, checkOut: D.checkOut })];
}
if (D.step === 'huespedes') {
  const values = (normalized.match(/\d+/g) || []).map(Number);
  const adults = values[0];
  const children = values.length > 1 ? values[1] : 0;
  const max = Number(D.room && D.room.maxAdultsCapacity || 0) + Number(D.room && D.room.childrenCapacity || 0);
  if (!adults || adults < 1 || children < 0) return [output('⚠️ Indica las personas así: *2 adultos y 1 niño*.', keep(D, 'huespedes'))];
  if (max && adults + children > max) return [output('⚠️ Esa habitación admite máximo *' + max + ' personas* según su capacidad. Regresa a la selección escribiendo *menú* o elige otra habitación.', keep(D, 'seleccion_habitacion'))];
  const base = Number(D.room && D.room.baseAdultsCapacity || 0);
  const extraPrice = Number(D.room && D.room.extraGuestPrice || 0);
  const extraGuests = Math.max(0, adults + children - base);
  const draft = Object.assign({}, D, { adults, children, extraGuests, extraGuestPrice: extraPrice, extraTotal: extraGuests * extraPrice });
  return [output('✅ Huéspedes registrados: *' + adults + ' adulto(s)* y *' + children + ' niño(s)*.\n\nIndica el nombre completo de la persona que hará la reserva.', keep(draft, 'nombre'))];
}
if (D.step === 'nombre') {
  if (text.length < 3) return [output('⚠️ Indica un nombre completo válido.', keep(D, 'nombre'))];
  return [output('Gracias. Ahora indica el número de identificación del titular de la reserva.', keep(Object.assign({}, D, { guestName: text }), 'identificacion'))];
}
if (D.step === 'identificacion') return [output('¿Viajas con mascota?', keep(Object.assign({}, D, { document: text }), 'mascota'), { response_payload: { type: 'interactive', interactive: { type: 'button', body: { text: '¿Viajas con mascota?' }, action: { buttons: [{ type: 'reply', reply: { id: 'pet_si', title: 'Sí' } }, { type: 'reply', reply: { id: 'pet_no', title: 'No' } }] } } } })];
if (D.step === 'mascota') {
  const hasPet = ['si', 'sí', 'pet_si', 'yes'].includes(normalized);
  const noPet = ['no', 'pet_no'].includes(normalized);
